async function api(url,method='GET',body){const r=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok){if(r.status===401&&user){user=null;void boot()}throw Error(d.error||'请求失败')}return d}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}function button(id,fn){const b=$('#'+id);if(b)b.onclick=async()=>{if(b.disabled)return;b.disabled=true;try{await fn()}catch(e){toast(e.message)}finally{b.disabled=false}}}function modal(title,html){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#modal').showModal()}$('#dialog-close').onclick=()=>$('#modal').close();
function badge(s){return `<span class="badge ${esc(s)}">${esc(statuses[s]||s)}</span>`}function date(s){return new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}function options(list,value='',empty='全部班级'){return `<option value="">${empty}</option>`+list.map(c=>`<option value="${esc(c.id)}" ${c.id===value?'selected':''}>${esc(c.name)}</option>`).join('')}function head(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${actions}</div></div>`}function empty(title,sub=''){return `<div class="empty"><b>${title}</b>${sub}</div>`}function card(title,html,action=''){return `<section class="card"><div class="card-head"><h2>${title}</h2>${action}</div>${html}</section>`}function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
async function boot(){const b=await api('/api/bootstrap');if(!b.user){user=null;$('#app').innerHTML=`<section class="login"><div class="brand"><span class="brand-mark">▦</span>课堂随记</div><h1>${b.needsSetup?'创建学校管理员':'登录班级工作台'}</h1><p class="sub">${b.needsSetup?'首次配置后即可导入学生、课表和座位，连接教室客户端。':'查看课堂观察、学生档案与评价结果。'}</p><form id="login-form">${b.needsSetup?'<label>姓名</label><input id="name" required autocomplete="name">':''}<label>账号</label><input id="username" required autocomplete="username"><label>密码${b.needsSetup?'（至少10位）':''}</label><input id="password" type="password" required autocomplete="${b.needsSetup?'new-password':'current-password'}"><button class="primary" type="submit">${b.needsSetup?'创建并进入':'登录'}</button><p id="login-error" class="note"></p></form><div style="margin-top:20px;padding-top:16px;border-top:1px solid #e2e8f0;display:flex;flex-direction:column;gap:8px;"><a href="/classroom.html" style="display:flex;align-items:center;justify-content:center;gap:6px;padding:10px 14px;border-radius:8px;background:#eef2ff;color:#4f6ef7;text-decoration:none;font-weight:600;font-size:13px;"><span>▦</span> 进入网页端随堂采集（免密设备码/平板） ↗</a></div></section>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const btt=$('#login-form button');btt.disabled=true;try{await api(b.needsSetup?'/api/setup':'/api/login','POST',{username:$('#username').value,password:$('#password').value,name:$('#name')?.value});await boot()}catch(e){$('#login-error').textContent=e.message}finally{btt.disabled=false}};return}user=b.user;await refresh();shell();await navigate(view)}
async function refresh(){state=await api('/api/state');user=state.user}function shell(){const nav=[['overview','◫','班级概览'],['reports','▤','评价报表'],['records','≡','课堂记录'],['students','♙','学生档案'],['classroom','▦','课堂采集']];if(user.role==='admin')nav.push(['config','⚙','配置'],['audit','↺','操作历史']);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">▦</span>课堂随记</div><div class="section-label">课堂与学生</div><nav>${nav.map(([id,icon,name])=>`<button class="nav-btn" data-view="${id}"><span class="icon">${icon}</span>${name}</button>`).join('')}</nav><div class="identity"><b>${esc(user.name)}</b><small>${roleNames[user.role]}</small></div></aside><section><header class="topbar"><strong>${esc(state.school.name)} / 班级工作台</strong><div class="actions"><a href="/classroom.html" target="_blank" style="text-decoration:none;display:inline-flex;align-items:center;gap:4px;padding:6px 10px;border-radius:6px;border:1px solid #cbd5e1;font-size:12px;color:#334155;background:#fff;"><span>▦</span> 独立采集端 ↗</a><span>${new Date().toLocaleDateString('zh-CN')}</span><button class="ghost" id="logout">退出</button></div></header><div id="content" class="content"></div></section></div>`;$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));button('logout',async()=>{if(activeCapture)throw Error('请先完成录音');await api('/api/logout','POST');view='overview';user=null;await boot()})}
